/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { HashMap } from '@jsverse/transloco';
import { Observable, map } from 'rxjs';
import { ConfirmDialogComponent } from './confirm-dialog.component';

export interface ConfirmOptions {
  messageKey: string;
  titleKey?: string;
  okKey?: string;
  cancelKey?: string;
  params?: HashMap;
}

/**
 * Diálogo de confirmación con textos traducidos.
 *
 * @example
 * this.confirm.confirm({ messageKey: 'identity.stepUp.message' }).subscribe((ok) => ok && this.save());
 */
@Injectable({ providedIn: 'root' })
export class ConfirmDialogService {
  private readonly dialog = inject(MatDialog);

  confirm(options: ConfirmOptions): Observable<boolean> {
    const data: Required<ConfirmOptions> = {
      titleKey: 'common.confirm.title',
      okKey: 'common.confirm.ok',
      cancelKey: 'common.confirm.cancel',
      params: {},
      ...options,
    };
    return this.dialog
      .open(ConfirmDialogComponent, { data, disableClose: true })
      .afterClosed()
      .pipe(map((result) => result === true));
  }
}
